SELECT id, store_id, product_id, revenue, NTILE(4) OVER (PARTITION BY store_id ORDER BY units DESC, id) AS units_bucket, CORR(units, revenue) OVER (PARTITION BY product_id) AS corr_units_revenue, ROW_NUMBER() OVER w_recent AS row_seq, AVG(revenue) OVER (ORDER BY sale_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS revenue_avg_3 FROM store_sales WINDOW w_recent AS (ORDER BY sale_date DESC, id)
